def f(s):
    s = s.replace(" ", "")
    s = list(s)
    if '=' in s:
        s.remove('=')

    operators = ['+', '-', '*']
    for operator in operators:
        if operator in s:
            s.remove(operator)

    stack = []
    stack.append(ord(s[0]))
    for i in range(1, len(s)):
        if s[i] in operators:
            b = stack.pop()
            a = stack.pop()
            if s[i] == '+':
                stack.append(a + b)
            elif s[i] == '-':
                stack.append(a - b)
            elif s[i] == '*':
                stack.append(a * b)
        else:
            stack.append(ord(s[i]))

    if len(stack) == 1:
        return stack[0]
    else:
        return -1

